BEGIN;
SET LOCAL search_path=extensions,public,pg_temp;
SELECT no_plan();
INSERT INTO auth.users(id,email,raw_app_meta_data) VALUES ('13300000-0000-4000-8000-000000000001','fleet-own@example.test','{"_invite_provisioned":true}'),('13300000-0000-4000-8000-000000000002','fleet-foreign@example.test','{"_invite_provisioned":true}');
CREATE TEMP TABLE fleet_tenants(kind text PRIMARY KEY,tenant_id uuid);
INSERT INTO fleet_tenants VALUES ('own',(public.provision_company_atomic('13300000-0000-4000-8000-000000000001','{"name":"Fleet fixture own","domain":"fleet-own.example.test","slug":"fleet-fixture-own"}')->>'id')::uuid),('foreign',(public.provision_company_atomic('13300000-0000-4000-8000-000000000002','{"name":"Fleet fixture foreign","domain":"fleet-foreign.example.test","slug":"fleet-fixture-foreign"}')->>'id')::uuid);
SELECT set_config('request.jwt.claims','{"role":"service_role"}',true);
UPDATE public.users SET must_change_password=false WHERE auth_user_id IN ('13300000-0000-4000-8000-000000000001','13300000-0000-4000-8000-000000000002');
INSERT INTO public.drivers(id,tenant_id,full_name_ar,primary_mobile,category,status) SELECT CASE kind WHEN 'own' THEN '13300000-0000-4000-8000-000000000011'::uuid ELSE '13300000-0000-4000-8000-000000000012'::uuid END,tenant_id,'Fleet driver fixture','0501330001','freelancer','active' FROM fleet_tenants;
CREATE TEMP TABLE fleet_results(kind text PRIMARY KEY,result jsonb);
CREATE TEMP TABLE handover_input(input jsonb);
INSERT INTO handover_input VALUES ('{"form_type":"handover","form_date":"2026-10-22","odometer_reading":120,"fuel_level":"full","overall_condition":"good","exterior_front":"ok","exterior_rear":"ok","exterior_left":"ok","exterior_right":"ok","interior_cabin":"ok","tires_front_left":"ok","tires_front_right":"ok","tires_rear_left":"ok","tires_rear_right":"ok","spare_tire":"ok","windshield":"ok","lights_headlights":"ok","lights_rear":"ok","ac_system":"ok","engine_compartment":"ok","registration_card_present":true,"insurance_card_present":true,"spare_tire_present":true,"jack_tools_present":true,"fire_extinguisher_present":true,"reflectors_present":true,"notes":"Observed fixture"}');
UPDATE handover_input SET input=jsonb_set(input,'{form_date}',to_jsonb((clock_timestamp() AT TIME ZONE 'Asia/Riyadh')::date::text));
GRANT ALL ON fleet_tenants,fleet_results,handover_input TO authenticated;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"13300000-0000-4000-8000-000000000001","aal":"aal2"}',true);
INSERT INTO fleet_results VALUES ('vehicle',public.save_fleet_vehicle('{"plate_number":"FLT1331","make":"Toyota","model":"Fleet fixture","odometer_current":100}'));
SELECT ok((SELECT result->>'id' IS NOT NULL FROM fleet_results WHERE kind='vehicle'),'vehicle created via caller RPC');
SELECT is((SELECT status::text FROM public.vehicles WHERE id=(SELECT (result->>'id')::uuid FROM fleet_results WHERE kind='vehicle')),'available','created vehicle has honest available state');
SELECT throws_ok($$SELECT public.save_fleet_vehicle('{"plate_number":"FLT1332","make":"Toyota","model":"Invalid assigned","status":"assigned"}')$$,'P0001','FLT015: status is managed by active assignments and maintenance','create cannot fabricate assignment status');
SELECT throws_ok($$SELECT public.save_fleet_vehicle('{"make":"Changed"}',(result->>'id')::uuid,999) FROM fleet_results WHERE kind='vehicle'$$,'P0001','FLT005: record changed; reload before saving','stale vehicle edit denied');
UPDATE fleet_results SET result=public.save_fleet_vehicle('{"color":"White"}',(result->>'id')::uuid,(result->>'version')::bigint) WHERE kind='vehicle';
SELECT is((SELECT color FROM public.vehicles WHERE id=(SELECT (result->>'id')::uuid FROM fleet_results WHERE kind='vehicle')),'White','vehicle edit persisted');
SELECT throws_ok($$SELECT public.save_fleet_vehicle('{"odometer_current":99}',(result->>'id')::uuid,(result->>'version')::bigint) FROM fleet_results WHERE kind='vehicle'$$,'P0001','FLT010: invalid vehicle values','vehicle odometer cannot regress');
INSERT INTO fleet_results SELECT 'assignment',public.mutate_fleet_assignment('assign',(result->>'id')::uuid,'13300000-0000-4000-8000-000000000011','{"handover_odometer":120}') FROM fleet_results WHERE kind='vehicle';
SELECT is((SELECT status::text FROM public.vehicles WHERE id=(SELECT (result->>'id')::uuid FROM fleet_results WHERE kind='vehicle')),'assigned','assignment updates parent vehicle');
SELECT ok((SELECT current_vehicle_id=(SELECT (result->>'id')::uuid FROM fleet_results WHERE kind='vehicle') FROM public.drivers WHERE id='13300000-0000-4000-8000-000000000011'),'assignment updates driver pointer');
SELECT throws_ok($$SELECT public.mutate_fleet_assignment('assign',(result->>'id')::uuid,'13300000-0000-4000-8000-000000000011') FROM fleet_results WHERE kind='vehicle'$$,'P0001','FLT016: driver or vehicle is no longer available','duplicate assignment denied');
SELECT throws_ok($$SELECT public.save_fleet_vehicle('{}',v.id,v.version,'Active fixture') FROM public.vehicles v JOIN fleet_results f ON v.id=(f.result->>'id')::uuid WHERE f.kind='vehicle'$$,'P0001','FLT013: end active assignments and maintenance before archiving','assigned vehicle cannot archive');
SELECT throws_ok($$SELECT public.save_fleet_handover((result->>'id')::uuid,'{"form_type":"handover"}') FROM fleet_results WHERE kind='assignment'$$,'P0001','FLT025: inspect and complete every checklist item','handover requires explicit full checklist');
INSERT INTO fleet_results SELECT 'handover',public.save_fleet_handover((result->>'id')::uuid,(SELECT input FROM handover_input)) FROM fleet_results WHERE kind='assignment';
SELECT ok((SELECT handover_form_id=(SELECT (result->>'id')::uuid FROM fleet_results WHERE kind='handover') FROM public.vehicle_assignments WHERE id=(SELECT (result->>'id')::uuid FROM fleet_results WHERE kind='assignment')),'handover attached to assignment');
UPDATE fleet_results SET result=public.save_fleet_handover((SELECT (result->>'id')::uuid FROM fleet_results WHERE kind='assignment'),(SELECT input||'{"notes":"Corrected inspection"}' FROM handover_input),(result->>'id')::uuid,(result->>'version')::bigint) WHERE kind='handover';
SELECT is((SELECT notes FROM public.vehicle_handover_forms WHERE id=(SELECT (result->>'id')::uuid FROM fleet_results WHERE kind='handover')),'Corrected inspection','draft handover correction persisted');
SELECT lives_ok($$SELECT public.archive_fleet_handover((result->>'id')::uuid,(result->>'version')::bigint,'Duplicate draft fixture') FROM fleet_results WHERE kind='handover'$$,'draft handover can archive');
INSERT INTO fleet_results SELECT 'final_handover',public.save_fleet_handover((result->>'id')::uuid,(SELECT input||'{"finalize":true}' FROM handover_input)) FROM fleet_results WHERE kind='assignment';
SELECT throws_ok($$SELECT public.archive_fleet_handover((result->>'id')::uuid,(result->>'version')::bigint,'Must preserve final history') FROM fleet_results WHERE kind='final_handover'$$,'P0001','FLT023: acknowledged handover history is immutable','finalized handover cannot archive');
SELECT ok((SELECT finalized_at IS NOT NULL AND driver_acknowledged_at IS NULL AND supervisor_acknowledged_at IS NULL FROM public.vehicle_handover_forms WHERE id=(SELECT (result->>'id')::uuid FROM fleet_results WHERE kind='final_handover')),'staff finalization does not fabricate driver or supervisor signature');
INSERT INTO fleet_results SELECT 'event1',public.mutate_maintenance_event('create',jsonb_build_object('vehicle_id',result->>'id','maintenance_type','repair','fault_description','First service fixture','odometer_at_service',120)) FROM fleet_results WHERE kind='vehicle';
INSERT INTO fleet_results SELECT 'event2',public.mutate_maintenance_event('create',jsonb_build_object('vehicle_id',result->>'id','maintenance_type','repair','fault_description','Second service fixture','odometer_at_service',120)) FROM fleet_results WHERE kind='vehicle';
UPDATE fleet_results SET result=public.mutate_maintenance_event('start','{}',(result->>'id')::uuid,(result->>'version')::bigint) WHERE kind='event1';
SELECT is((SELECT status::text FROM public.vehicles WHERE id=(SELECT (result->>'id')::uuid FROM fleet_results WHERE kind='vehicle')),'in_maintenance','start holds vehicle atomically');
SELECT throws_ok($$SELECT public.mutate_maintenance_event('complete','{"cost":12}',(result->>'id')::uuid,1) FROM fleet_results WHERE kind='event1'$$,'P0001','FLT005: record changed; reload before saving','stale event completion denied');
UPDATE fleet_results SET result=public.mutate_maintenance_event('complete','{"cost":12.34,"odometer_at_service":125}',(result->>'id')::uuid,(result->>'version')::bigint) WHERE kind='event1';
SELECT is((SELECT status::text FROM public.vehicles WHERE id=(SELECT (result->>'id')::uuid FROM fleet_results WHERE kind='vehicle')),'in_maintenance','one completed event does not release another active event hold');
SELECT is((SELECT odometer_current FROM public.vehicles WHERE id=(SELECT (result->>'id')::uuid FROM fleet_results WHERE kind='vehicle')),125,'completion odometer mirrored atomically');
SELECT throws_ok($$SELECT public.mutate_maintenance_event('update','{"fault_description":"Cannot change history"}',(result->>'id')::uuid,(result->>'version')::bigint) FROM fleet_results WHERE kind='event1'$$,'P0001','FLT007: finalized or started maintenance history cannot be changed by this operation','completed event history immutable');
UPDATE fleet_results SET result=public.mutate_fleet_assignment('unassign',(SELECT (result->>'id')::uuid FROM fleet_results WHERE kind='vehicle'),'13300000-0000-4000-8000-000000000011','{}',(SELECT version FROM public.vehicle_assignments WHERE id=(result->>'id')::uuid)) WHERE kind='assignment';
SELECT is((SELECT status::text FROM public.vehicles WHERE id=(SELECT (result->>'id')::uuid FROM fleet_results WHERE kind='vehicle')),'in_maintenance','unassignment preserves remaining maintenance hold');
SELECT ok((SELECT current_vehicle_id IS NULL FROM public.drivers WHERE id='13300000-0000-4000-8000-000000000011'),'unassign clears driver pointer');
UPDATE fleet_results SET result=public.mutate_maintenance_event('cancel','{"reason":"No second service needed"}',(result->>'id')::uuid,(result->>'version')::bigint) WHERE kind='event2';
SELECT is((SELECT status::text FROM public.vehicles WHERE id=(SELECT (result->>'id')::uuid FROM fleet_results WHERE kind='vehicle')),'available','last active maintenance closure releases unassigned vehicle');
SELECT lives_ok($$SELECT public.record_fleet_odometer((result->>'id')::uuid,130) FROM fleet_results WHERE kind='vehicle'$$,'odometer observation commits with parent');
SELECT throws_ok($$SELECT public.record_fleet_odometer((result->>'id')::uuid,129) FROM fleet_results WHERE kind='vehicle'$$,'P0001','VEH003: odometer reading cannot move backwards','regressive odometer rejected');
SELECT throws_ok($$UPDATE public.vehicles SET make='Bypass' WHERE id=(SELECT (result->>'id')::uuid FROM fleet_results WHERE kind='vehicle')$$,'42501',NULL,'direct vehicle mutation bypass denied');
SELECT throws_ok($$INSERT INTO public.vehicle_maintenance_events(tenant_id,vehicle_id,maintenance_type) SELECT tenant_id,(SELECT (result->>'id')::uuid FROM fleet_results WHERE kind='vehicle'),'repair' FROM fleet_tenants WHERE kind='own'$$,'42501',NULL,'direct maintenance mutation bypass denied');
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"13300000-0000-4000-8000-000000000002","aal":"aal2"}',true);
SELECT throws_ok($$SELECT public.save_fleet_vehicle('{"color":"Foreign edit"}',(result->>'id')::uuid,1) FROM fleet_results WHERE kind='vehicle'$$,'P0001','FLT003: active tenant vehicle not found','foreign vehicle mutation denied');
SELECT throws_ok($$SELECT public.mutate_maintenance_event('start','{}',(result->>'id')::uuid,(result->>'version')::bigint) FROM fleet_results WHERE kind='event2'$$,'P0001','FLT003: active tenant vehicle not found','foreign event denied');
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"13300000-0000-4000-8000-000000000001","aal":"aal1"}',true);
SELECT throws_ok($$SELECT public.save_fleet_vehicle('{"plate_number":"FLT1333","make":"Toyota","model":"MFA denied"}')$$,'P0001','AUTH007: vehicle permission and verified session required','MFA required for caller writes');
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"13300000-0000-4000-8000-000000000001","aal":"aal2"}',true);
RESET ROLE;
INSERT INTO storage.objects(bucket_id,name,owner_id,metadata)
SELECT 'vehicle-documents',t.tenant_id::text||'/'||(v.result->>'id')||'/fixture.pdf','13300000-0000-4000-8000-000000000001','{"size":128,"mimetype":"application/pdf"}'::jsonb FROM fleet_tenants t CROSS JOIN fleet_results v WHERE t.kind='own' AND v.kind='vehicle';
SET LOCAL ROLE authenticated;
INSERT INTO fleet_results SELECT 'document',public.mutate_fleet_document('save',(v.result->>'id')::uuid,jsonb_build_object('doc_type','registration','doc_number','Fleet DOC','file_url',t.tenant_id::text||'/'||(v.result->>'id')||'/fixture.pdf','issue_date','2026-10-01','expiry_date','2027-10-01')) FROM fleet_tenants t CROSS JOIN fleet_results v WHERE t.kind='own' AND v.kind='vehicle';
SELECT is((SELECT doc_number FROM public.vehicle_documents WHERE id=(SELECT (result->>'id')::uuid FROM fleet_results WHERE kind='document')),'Fleet DOC','owned private document registered');
SELECT throws_ok($$SELECT public.mutate_fleet_document('save',(result->>'id')::uuid,'{"doc_type":"insurance","file_url":"foreign/vehicle/file.pdf"}') FROM fleet_results WHERE kind='vehicle'$$,'P0001','FLT020: document file must belong to this vehicle','foreign storage path denied');
SELECT throws_ok($$SELECT public.mutate_fleet_document('save',(v.result->>'id')::uuid,jsonb_build_object('doc_type','insurance','file_url',t.tenant_id::text||'/'||(v.result->>'id')||'/missing.pdf')) FROM fleet_tenants t CROSS JOIN fleet_results v WHERE t.kind='own' AND v.kind='vehicle'$$,'P0001','FLT021: a new owned document upload is required','unowned or missing storage object denied');
UPDATE fleet_results SET result=public.mutate_fleet_document('save',(SELECT (result->>'id')::uuid FROM fleet_results WHERE kind='vehicle'),'{"notes":"Edited doc metadata"}',(result->>'id')::uuid,(result->>'version')::bigint) WHERE kind='document';
SELECT is((SELECT notes FROM public.vehicle_documents WHERE id=(SELECT (result->>'id')::uuid FROM fleet_results WHERE kind='document')),'Edited doc metadata','document metadata edit persisted');
UPDATE fleet_results SET result=public.mutate_fleet_document('verify',(SELECT (result->>'id')::uuid FROM fleet_results WHERE kind='vehicle'),'{}',(result->>'id')::uuid,(result->>'version')::bigint) WHERE kind='document';
SELECT ok((SELECT is_verified AND verified_by=auth.uid() AND verified_at IS NOT NULL FROM public.vehicle_documents WHERE id=(SELECT (result->>'id')::uuid FROM fleet_results WHERE kind='document')),'verification attributed to authenticated actor');
SELECT throws_ok($$SELECT public.mutate_fleet_document('save',(SELECT (result->>'id')::uuid FROM fleet_results WHERE kind='vehicle'),'{"notes":"Cannot change approved doc"}',(result->>'id')::uuid,(result->>'version')::bigint) FROM fleet_results WHERE kind='document'$$,'P0001','FLT019: verified documents are immutable; upload a replacement','verified document immutable');
SELECT lives_ok($$SELECT public.mutate_fleet_document('archive',(SELECT (result->>'id')::uuid FROM fleet_results WHERE kind='vehicle'),'{"reason":"Expired fixture document"}',(result->>'id')::uuid,(result->>'version')::bigint) FROM fleet_results WHERE kind='document'$$,'document can archive with reason');
RESET ROLE;
SELECT ok((SELECT deleted_at IS NOT NULL AND NOT is_active FROM public.vehicle_documents WHERE id=(SELECT (result->>'id')::uuid FROM fleet_results WHERE kind='document')),'archived document retained as inactive history');
SELECT is((SELECT count(*)::int FROM storage.objects WHERE bucket_id='vehicle-documents' AND owner_id='13300000-0000-4000-8000-000000000001'),1,'document archival retains original private object');
CREATE FUNCTION pg_temp.reject_fleet_audit() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.action='vehicle_created' THEN RAISE EXCEPTION 'fleet audit failure'; END IF;RETURN NEW;END;$$;
CREATE TRIGGER fleet_audit_fault BEFORE INSERT ON public.audit_log FOR EACH ROW EXECUTE FUNCTION pg_temp.reject_fleet_audit();
SET LOCAL ROLE authenticated;
SELECT throws_ok($$SELECT public.save_fleet_vehicle('{"plate_number":"FLT1334","make":"Toyota","model":"Rollback fixture"}')$$,'P0001','fleet audit failure','audit failure rolls back full vehicle operation');
RESET ROLE;
SELECT is((SELECT count(*)::int FROM public.vehicles WHERE plate_number='FLT1334' AND tenant_id=(SELECT tenant_id FROM fleet_tenants WHERE kind='own')),0,'failed audit leaves no vehicle');
DROP TRIGGER fleet_audit_fault ON public.audit_log;
SET LOCAL ROLE authenticated;
SELECT lives_ok($$SELECT public.save_fleet_vehicle('{}',v.id,v.version,'Retired fixture') FROM public.vehicles v JOIN fleet_results f ON v.id=(f.result->>'id')::uuid WHERE f.kind='vehicle'$$,'vehicle archives after operational holds ended');
RESET ROLE;
SELECT ok((SELECT deleted_at IS NOT NULL FROM public.vehicles WHERE id=(SELECT (result->>'id')::uuid FROM fleet_results WHERE kind='vehicle')),'archive retains vehicle history');
SELECT ok((SELECT count(*)>10 FROM public.audit_log WHERE tenant_id=(SELECT tenant_id FROM fleet_tenants WHERE kind='own') AND module IN ('vehicles','maintenance')),'atomic fleet workflow emits audit history');
SET LOCAL ROLE anon;
SELECT throws_ok($$SELECT public.save_fleet_vehicle('{}')$$,'42501',NULL,'anonymous execution denied');
RESET ROLE;
SELECT * FROM finish();
ROLLBACK;
